CREATE DATABASE bdd_medicale_fictive;

USE bdd_medicale_fictive;

CREATE TABLE Patients(
    id_patient INT AUTO_INCREMENT,
    nom VARCHAR(100) NOT NULL,
    date_naissance DATE NOT NULL,
    groupe_sanguin VARCHAR(3) NOT NULL,
    CONSTRAINT pk_patients PRIMARY KEY(id_patient)
);
CREATE TABLE Medecins (
    id_medecin INT AUTO_INCREMENT,
    nom VARCHAR(100) NOT NULL,
    specialite VARCHAR(100) NOT NULL,
    CONSTRAINT pk_medecins PRIMARY KEY(id_medecin)
);
CREATE TABLE Consultations (
    id_consultation int auto_increment,
    id_patient int,
    id_medecin int,
    date_consultation datetime,
    diagnostic TEXT,
    CONSTRAINT pk_consultations PRIMARY KEY(id_consultation),
    CONSTRAINT fk_consultations_patients FOREIGN KEY(id_patient) REFERENCES Patients(id_patient),
    CONSTRAINT fk_consultations_medecins FOREIGN KEY(id_medecin) REFERENCES Medecins(id_medecin)
);
CREATE TABLE Medicaments (
    id_medicament int auto_increment,
    nom_commercial varchar (100) unique,
    CONSTRAINT pk_medicaments PRIMARY KEY(id_medicament)
);
CREATE TABLE Prescriptions (
    id_prescription int auto_increment,
    id_consultation int,
    date_prescription date,
    CONSTRAINT pk_prescriptions PRIMARY KEY(id_prescription),
    CONSTRAINT fk_prescriptions_consultations FOREIGN KEY(id_consultation) REFERENCES Consultations(id_consultation)
);
CREATE TABLE Prescription_medicament (
    id_prescription int,
    id_medicament int,
    dosage decimal (5, 2),
    duree int,
    CONSTRAINT pk_prescription_medicament PRIMARY KEY(id_prescription, id_medicament),
    CONSTRAINT fk_prescription_medicament_prescriptions FOREIGN KEY(id_prescription) REFERENCES Prescriptions(id_prescription),
    CONSTRAINT fk_prescription_medicament_medicaments FOREIGN KEY(id_medicament) REFERENCES Medicaments(id_medicament)
);
CREATE TABLE Rendez_vous (
    id_patient int,
    id_medecin int,
    date_rendez_vous date NOT NULL,
    motif TEXT NOT NULL,
    CONSTRAINT pk_rendez_vous PRIMARY KEY(id_patient, id_medecin, date_rendez_vous),
    CONSTRAINT fk_rendez_vous_patients FOREIGN KEY(id_patient) REFERENCES Patients(id_patient),
    CONSTRAINT fk_rendez_vous_medecins FOREIGN KEY(id_medecin) REFERENCES Medecins(id_medecin)
);

